1	// sc4sap:program-to-spec — Template-clone xlsx renderer.
2	//
3	// Strategy (양식 보존 / format-preserving):
4	//   1. Read asset/template_base.xlsx (canonical reference workbook —
5	//      English-source ZMMRTEST003 spec with all styles, borders, fonts, column
6	//      widths, row heights, drawings, images intact).
7	//   2. Re-zip every entry byte-for-byte EXCEPT xl/sharedStrings.xml.
8	//   3. For xl/sharedStrings.xml, replace each <t>…</t> content using the
9	//      user-supplied translation map TR { "English key": "한국어 값" }.
10	//   4. Write the resulting xlsx to outPath.
11	//
12	// Why this exists:
13	//   The previous workflow built xlsx geometry from JSON (SHEETS_DATA + custom
14	//   styles), which silently drifted from the agreed reference format. By
15	//   cloning the template and only swapping text payload, the output is GUARANTEED
16	//   to match the reference layout exactly — styles, borders, image anchors,
17	//   row heights, column widths all preserved.
18	//
19	// Slot semantics (must be honoured by the TR map producer — sap-writer):
20	//   · Sheet 1 (Program Overview): 17 Field/Value rows
21	//   · Sheet 2 (Data Model):       4 table rows (slots: VBAK → MARA-style, VBAP →
22	//                                 MARC-style, KNA1 → MAKT-style, MAKT → 4th) +
23	//                                 CDS Views / BAPIs / BAdIs trailer rows
24	//   · Sheet 3 (Inputs & Screens): 5 parameter slots (S_VKORG..S_VBELN) + 5
25	//                                 warning rows. Repurpose unused slots with
26	//                                 "— (해당 없음)" placeholders to keep row count.
27	//   · Sheet 4 (Processing Logic): 12 step slots. Use "—" for unused.
28	//   · Sheet 5 (Output):           10 ALV column slots. Use "—" for unused.
29	//   · Sheet 6 (Authorizations):   5 rows.
30	//   · Sheet 7 (Exceptions):       3 rows.
31	//
32	// SAP standard identifiers (table names, field names, parameter names) that
33	// happen to match the source spec (ZMMRTEST003 / VBAK / VBELN / S_VKORG …)
34	// MUST be present as TR keys to swap them for the target program's identifiers.
35	// Identifiers absent from TR remain in the cloned file unchanged.
36	
37	import { readFileSync, writeFileSync, existsSync } from 'node:fs';
38	import { dirname, resolve } from 'node:path';
39	import { fileURLToPath } from 'node:url';
40	import { unzipEntries, zipFiles } from './xlsx-zip.mjs';
41	
42	const __dirname = dirname(fileURLToPath(import.meta.url));
43	
44	// =============================================================
45	// sharedStrings.xml translation
46	// =============================================================
47	function translateSharedStrings(xml, tr, { warnUntranslated = true } = {}) {
48	  const missing = [];
49	  const out = xml.replace(/<t([^>]*)>([\s\S]*?)<\/t>/g, (m, attrs, body) => {
50	    const decoded = body
51	      .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
52	      .replace(/&quot;/g, '"').replace(/&apos;/g, "'")
53	      .replace(/&amp;/g, '&');
54	    const translated = tr[decoded];
55	    if (translated == null) {
56	      // English-looking strings that lack a mapping are likely bugs in the TR map.
57	      // Pure-ASCII single tokens (table names, field codes) are intentionally
58	      // unmapped when the target program shares the identifier.
59	      if (warnUntranslated && /[A-Za-z]/.test(decoded) && decoded.length > 1) {
60	        missing.push(decoded.slice(0, 80));
61	      }
62	      return m;
63	    }
64	    const enc = translated
65	      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
66	      .replace(/"/g, '&quot;').replace(/'/g, '&apos;');
67	    const needsSpace = /^\s|\s$|\n/.test(translated);
68	    const newAttrs = needsSpace && !/xml:space/.test(attrs)
69	      ? ' xml:space="preserve"' + attrs : attrs;
70	    return `<t${newAttrs}>${enc}</t>`;
71	  });
72	  return { xml: out, missing };
73	}
74	
75	// =============================================================
76	// Public API
77	// =============================================================
78	export function cloneTemplate({ outPath, tr, templatePath, verbose = true }) {
79	  // Default: <repo-root>/asset/template_base.xlsx (two levels up from scripts/spec/).
80	  const tplPath = templatePath
81	    || resolve(__dirname, '..', '..', 'asset', 'template_base.xlsx');
82	  if (!existsSync(tplPath)) {
83	    throw new Error(`template-clone: template not found at ${tplPath}`);
84	  }
85	  const src = readFileSync(tplPath);
86	  const entries = unzipEntries(src);
87	  let foundSS = false;
88	  let missing = [];
89	  for (const e of entries) {
90	    if (e.name === 'xl/sharedStrings.xml') {
91	      foundSS = true;
92	      const result = translateSharedStrings(e.data.toString('utf8'), tr);
93	      e.data = Buffer.from(result.xml, 'utf8');
94	      missing = result.missing;
95	    }
96	  }
97	  if (!foundSS) throw new Error('template-clone: xl/sharedStrings.xml missing from template');
98	  const out = zipFiles(entries);
99	  writeFileSync(outPath, out);
100	  if (verbose) {
101	    console.log(`template-clone: wrote ${outPath} (${out.length} bytes)`);
102	    if (missing.length > 0) {
103	      console.log(`template-clone: ${missing.length} English string(s) had no TR mapping:`);
104	      for (const s of missing.slice(0, 20)) console.log(`  · ${JSON.stringify(s)}`);
105	      if (missing.length > 20) console.log(`  · … (${missing.length - 20} more)`);
106	    }
107	  }
108	  return { outPath, bytes: out.length, missing };
109	}
110	
111	// CLI usage:  node template-clone.mjs <tr-json-path> <out-xlsx-path>
112	// Run unconditionally when invoked as the entrypoint script (process.argv[1]
113	// equals this file). On Windows, fileURLToPath round-trip handles drive-letter
114	// + backslash mismatches that broke the older `file://` comparison.
115	const thisFile = fileURLToPath(import.meta.url);
116	if (process.argv[1] && resolve(process.argv[1]) === thisFile) {
117	  const [trPath, outPath] = process.argv.slice(2);
118	  if (!trPath || !outPath) {
119	    console.error('Usage: node template-clone.mjs <tr-json-path> <out-xlsx-path>');
120	    process.exit(2);
121	  }
122	  const tr = JSON.parse(readFileSync(trPath, 'utf8'));
123	  cloneTemplate({ outPath, tr });
124	}
